739	// A repository with no `origin/HEAD` (a fresh clone, or one built by hand, as in tests)
740	// fails this on the common path, not just exceptionally.
741	fn local_origin_head<R: CommandRunner>(runner: &R, root: &Path) -> Option<String> {
742	    let output = runner
743	        .run_quiet(
744	            programs::GIT,
745	            &["symbolic-ref", "refs/remotes/origin/HEAD"],
746	            root,
747	            timeouts::LOCAL_GIT,
748	        )
749	        .ok()?;
750	    if output.exit_code != Some(0) {
