756	// A shallow or hand-built clone (or one `remote set-head` never ran on) has no local
757	// `origin/HEAD`; asking the remote directly still resolves it without a fetch.
758	fn remote_origin_head<R: CommandRunner>(runner: &R, root: &Path) -> Option<String> {
759	    let output = runner
760	        .run_quiet(
761	            programs::GIT,
762	            &["ls-remote", "--symref", "origin", "HEAD"],
763	            root,
764	            timeouts::GIT_LS_REMOTE,
765	        )
766	        .ok()?;
767	    if output.exit_code != Some(0) {
768	        return None;
769	    }
770	    // Output line shape: "ref: refs/heads/<branch>\tHEAD".
771	    output.stdout.lines().find_map(|line| {
772	        let (target, name) = line.strip_prefix("ref: ")?.split_once('\t')?;
773	        (name.trim() == "HEAD").then(|| last_ref_segment(target))?
774	    })
775	}
