778	// actually checked out is a better guess than a hardcoded `main`.
779	fn current_branch<R: CommandRunner>(runner: &R, root: &Path) -> Option<String> {
780	    let output = runner
781	        .run_quiet(
782	            programs::GIT,
783	            &["symbolic-ref", "--short", "HEAD"],
784	            root,
785	            timeouts::LOCAL_GIT,
786	        )
