803	/// Installs the Python build and upload tools into a venv put on the PATH of the later steps; carries no secrets.
804	const SIMPLE_PYTHON_TOOLS_STEP: &str = "      - name: Install the Python publishing tools
805	        run: |
806	          set -euo pipefail
807	          python3 -m venv \"$RUNNER_TEMP/publish-venv\"
808	          \"$RUNNER_TEMP/publish-venv/bin/python\" -m pip install --quiet __BUILD__ __TWINE__
809	          echo \"$RUNNER_TEMP/publish-venv/bin\" >> \"$GITHUB_PATH\"
810	";
