812	/// Resolves `callisto@<version>`'s commit SHA on `orin-dx/callisto`'s remote.
813	///
814	/// GitHub's runner splits a `uses:` reference at the LAST `@` in the whole
815	/// string (`ActionManifestManagerWrapper.ParseActionReference` in
816	/// `actions/runner`), so a ref that itself contains `@` -- like the
817	/// `callisto@<version>` tag this project releases under -- can never be
818	/// written directly as `owner/repo/path@callisto@<version>`: the split lands
819	/// inside the ref, not before it, and resolution fails. The generated
820	/// workflow pins to this tag's resolved commit instead, like every other
821	/// external action reference in this repository.
822	///
823	/// # Errors
824	///
825	/// The remote is unreachable, or `callisto@<version>` is not a published tag.
826	pub fn resolve_release_commit<R: CommandRunner>(runner: &R, root: &Path, version: &str) -> Result<String, GraphError> {
827	    const ENDPOINT: &str = "https://github.com/orin-dx/callisto.git";
828	    let reference = format!("refs/tags/callisto@{version}");
829	    // The peeled ref resolves an annotated tag to its commit; a lightweight
830	    // tag has no peeled line, and its own SHA already is the commit.
831	    let peeled = format!("{reference}^{{}}");
832	    // A transport-level failure (git not found, timed out, ...) keeps its
833	    // real cause via `GraphError::Command`; only a clean run that still
834	    // can't find the tag becomes `InitWorkflowVersionUnresolved`.
835	    let output = runner.run_quiet(
836	        programs::GIT,
837	        &["ls-remote", ENDPOINT, &reference, &peeled],
838	        root,
839	        timeouts::GIT_LS_REMOTE,
840	    )?;
841	    let unresolved = || GraphError::InitWorkflowVersionUnresolved {
842	        version: version.to_owned(),
843	    };
844	    if output.exit_code != Some(0) {
845	        return Err(unresolved());
846	    }
847	    let mut tag_object = None;
848	    let mut commit = None;
849	    for line in output.stdout.lines() {
850	        let Some((sha, found)) = line.split_once('\t') else {
851	            continue;
852	        };
853	        match found.trim() {
854	            found if found == peeled => commit = Some(sha.trim().to_owned()),
855	            found if found == reference => tag_object = Some(sha.trim().to_owned()),
856	            _ => {}
857	        }
858	    }
859	    commit.or(tag_object).ok_or_else(unresolved)
860	}
