/// The text of `job`'s block: from its `  <job>:` line to the next job's.
fn job<'a>(workflow: &'a str, job: &str) -> &'a str {
    let start = workflow
        .find(&format!("\n  {job}:\n"))
        .unwrap_or_else(|| panic!("no job `{job}`"))
        + 1;
    let rest = &workflow[start..];
    let end = rest
        .match_indices("\n  ")
        .find(|(index, _)| !rest[index + 3..].starts_with(' '))

